# frozen_string_literal: true

# Sample Policy generated by Antigravity Ruby SDK 🛰️
# Demonstrates paths/cmds DSL syntax, read/write scoping, and sensitive file protections.

Antigravity.policy do
  # Read access for documentation and repositories
  allow :read_file, when: paths(
    '~/git/sre/*',
    '~/git/pvt-skillume/*',
    'docs/*.md'
  )

  # Write access for output sandboxes and source code
  allow :write_file, when: paths(
    'out/*',
    'scratch/*',
    'lib/*'
  )

  # Sensitive files: allow reading, but strictly deny editing!
  allow :read_file, when: paths('.env', 'GEMINI.md')
  deny :write_file, when: paths('.env', 'GEMINI.md')

  # Common safe developer shell commands
  allow :run_command, when: cmds(
    'git status',
    'git diff',
    'gcloud auth list',
    'just test'
  )
end
